head.script:
scwin.nowDate;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.chkParam();
        await scwin.listSet();
        await scwin.getList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT10005.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dsetNotEndLst_OnLoadCompleted
 * @description dsetNotEndLst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dsetNotEndLst_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name dsetNotEndLst_OnLoadError
 * @description dsetNotEndLst 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dsetNotEndLst_OnLoadError = async function() {
    try {
        await $c.win.alert('dsetNotEndLst.OnLoadError()');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT10005.dsetNotEndLst_OnLoadError" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getList
 * @description get List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getList = async function() {
    const sbmOptions = {
        id : "sbm_dsetNotEndLst",
        action : "/bzchklist.do",
        ref : "",
        target : "dsetNotEndLst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSet
 * @description list Set 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSet = async function() {
    const sbmOptions = {
        id : "sbm_dsetNotEndLst",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dsetNotEndLst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name chkParam
 * @description chk Param 처리
 * @returns {void}
 * @hidden N
 */
scwin.chkParam = function() {
    const param = location.search.split("&")[0];
    scwin.nowDate = param.substr(param.length - 8);
};
